package net.officefloor.hq.app.plan;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;
import net.officefloor.server.http.ServerHttpConnection;
import org.springframework.web.bind.annotation.RequestBody;

public class PausePlan {
    // Pauses the plan on the sheet's today (PLAN_PAUSED), or resumes it on the sheet's today (PLAN_RESUMED). Pausing a
    // paused plan or resuming a running one is refused, before anything is stored or recorded.
    public void pause(@RequestBody PlanPauseRequest body, @Val Plan plan, @Val Person person, Plans plans, Sheets sheets,
            ServerHttpConnection connection, Audit audit) throws PlanRefusedException {
        boolean pause = body != null && body.paused();
        if (pause == plans.paused(plan.id())) {
            throw new PlanRefusedException(pause ? "The plan is already paused." : "The plan is not paused.");
        }
        if (pause) {
            plans.pause(plan.id(), sheets.today(plan.sheetId()));
        } else {
            plans.resume(plan.id(), sheets.today(plan.sheetId()));
        }
        audit.record(Audit.line(pause ? "PLAN_PAUSED" : "PLAN_RESUMED", plan.sheetId(), Audit.user(connection),
                "name=" + person.name(), "start=" + plan.start()));
    }
}
=== java/net/officefloor/hq/app/plan/Plan.java
package net.officefloor.hq.app.plan;

import java.math.BigDecimal;
import java.time.LocalDate;

import java.util.ArrayList;
import java.util.List;

/** A person's plan: a DRAFT claim of {@code amount} on the start date, then every {@code every} days, up to the end date;
 *  or, when {@code day} is 1 to 31 (and {@code every} 0), on that day of every month from the start's month (a day beyond
 *  the month's length on its last day), dates before the start left out. */
public record Plan(long id, String sheetId, long personId, BigDecimal amount, LocalDate start, int every, LocalDate end,
        int day) {

    public boolean monthly() {
        return day > 0;
    }

    /** The plan's dates up to and including {@code last}, in order. */
    public List<LocalDate> dates(LocalDate last) {
        List<LocalDate> dates = new ArrayList<>();
        if (monthly()) {
            for (LocalDate month = start.withDayOfMonth(1); !month.isAfter(last); month = month.plusMonths(1)) {
                LocalDate date = month.withDayOfMonth(Math.min(day, month.lengthOfMonth()));
                if (!date.isBefore(start) && !date.isAfter(last)) {
                    dates.add(date);
                }
            }
        } else {
            for (LocalDate date = start; !date.isAfter(last); date = date.plusDays(every)) {
                dates.add(date);
            }
        }
        return dates;
    }

    /** The plan's dates up to and including {@code last} that none of its pauses skips, in order. */
    public List<LocalDate> dates(LocalDate last, List<PlanPause> pauses) {
        return dates(last).stream().filter(d -> pauses.stream().noneMatch(p -> p.skips(d))).toList();
    }

    /** The first {@code count} of the plan's dates after {@code today} and on or before its end that none of its pauses
     *  skips (none while it is paused and not resumed), in order. */
    public List<LocalDate> nextDates(LocalDate today, int count, List<PlanPause> pauses) {
        return dates(end, pauses).stream().filter(d -> d.isAfter(today)).limit(count).toList();
    }
}
